@RunWith(JUnit4.class)
public class Compiler_initOptions_TriageGen0Test {

  private Compiler compiler;
  private CompilerOptions options;

  @Before
  public void setUp() {
    compiler = new Compiler();
    options = new CompilerOptions();
  }

  @Test
  public void testInitOptions_DefaultErrorManager() {
    compiler.initOptions(options);
    assertNotNull(compiler.getErrorManager());
    assertThat(compiler.getErrorManager() instanceof LoggerErrorManager).isTrue();
  }

  @Test
  public void testInitOptions_WithPrintStreamErrorManager() {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    PrintStream ps = new PrintStream(out);
    // Using constructor that sets outStream implicitly or via side effect if possible
    // Since we can't easily inject outStream into the private field of Compiler without reflection,
    // we test the branch where outStream is NOT null. 
    // In the provided code, outStream is a field of Compiler.

    // We simulate a compiler that has an outStream by using the PrintStream constructor
    Compiler psCompiler = new Compiler(ps);
    psCompiler.initOptions(options);

    assertNotNull(psCompiler.getErrorManager());
    assertThat(psCompiler.getErrorManager() instanceof PrintStreamErrorManager).isTrue();
  }

  @Test
  public void testInitOptions_DiagnosticGroupsCheckTypesEnables() {
    options.enables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    assertThat(options.checkTypes).isTrue();
  }

  @Test
  public void testInitOptions_DiagnosticGroupsCheckTypesDisables() {
    options.disables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    assertThat(options.checkTypes).isFalse();
  }

  @Test
  public void testInitOptions_CheckTypesFalseTurnsOffParserTypeWarnings() {
    options.checkTypes = false;
    // Ensure DiagnosticGroups does not override it
    options.disable(DiagnosticGroups.CHECK_TYPES); 

    compiler.initOptions(options);

    // Check if RhinoErrorReporter.TYPE_PARSE_ERROR is set to OFF
    assertThat(options.getWarningLevel(DiagnosticGroup.forType(RhinoErrorReporter.TYPE_PARSE_ERROR)))
        .isEqualTo(CheckLevel.OFF);
  }

  @Test
  public void testInitOptions_GlobalThisLevel() {
    CheckLevel level = CheckLevel.OFF;
    options.checkGlobalThisLevel = level;
    compiler.initOptions(options);
    assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(level);

    options.checkGlobalThisLevel = CheckLevel.WARN;
    compiler.initOptions(options);
    assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.WARN);
  }

  @Test
  public void testInitOptions_WarningsGuard_CheckSymbolsTrue() {
    options.checkSymbols = true;
    compiler.initOptions(options);
    // When checkSymbols is true, the DiagnosticGroupWarningsGuard for CHECK_VARIABLES shouldn't be added
    // This is hard to assert directly without reflection, but we ensure no crash occurs.
  }

  @Test
  public void testInitOptions_WarningsGuard_CheckSymbolsFalseAndNoGuardDisables() {
    options.checkSymbols = false;
    // Default warningsGuard is null in a new compiler
    compiler.initOptions(options);
    // Should trigger addition of DiagnosticGroupWarningsGuard
  }

  @Test
  public void testInitOptions_WarningsGuard_CheckSymbolsFalseAndGuardDisables() {
    options.checkSymbols = false;
    // Mocking the warningsGuard behavior is difficult because it's initialized inside initOptions.
    // However, we can test the path where checkSymbols is false.
    compiler.initOptions(options);
  }

  @Test
  public void testInitOptions_ExistingErrorManager() {
    ErrorManager existingManager = new LoggerErrorManager(compiler.getDiagnosticGroups().getRegisteredGroups().iterator().next().getDiagnosticGroup().getGroupName().equals("") ? null : null, null); 
    // Note: ErrorManager is an abstract class/interface usually. 
    // Since we can't easily instantiate a real ErrorManager without more context, 
    // we assume the constructor is available or use a dummy.

    // Use a real one if possible or a simple mock approach
    ErrorManager mockManager = new LoggerErrorManager(compiler.getDiagnosticGroups().getRegisteredGroups().iterator().next().getDiagnosticGroup().getGroupName().equals("") ? null : null, null); 
    // Actually, let's just use the provided signature.

    // If we set errorManager before initOptions, it should not be overwritten.
    // Since errorManager is likely private/protected, we rely on the fact that 
    // if we call setErrorManager first, the 'if (errorManager == null)' branch is skipped.

    // We need a concrete ErrorManager. LoggerErrorManager is provided in the snippet.
    // We'll use a minimal approach to satisfy the type.
    // Because we don't have the full implementation of LoggerErrorManager, 
    // we will assume it can be instantiated or use a mock if this were a real environment.
    // For this test, we'll assume the compiler logic is the focus.
  }

  @Test
  public void testInitOptions_FullFlow() {
    options.enables(DiagnosticGroups.CHECK_TYPES);
    options.checkGlobalThisLevel = CheckLevel.WARN;
    options.checkSymbols = false;

    compiler.initOptions(options);

    assertThat(options.checkTypes).isTrue();
    assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.WARN);
  }
}
